// Template schemas are shared by guided inputs, checks, and editable instructions.
export const categories = ['Write & communicate', 'Explain & document', 'Plan & organize', 'Review & compare', 'Summarize & extract'];
export const roles = ['IT & technical support', 'Marketing & content', 'Customer support', 'Business & operations', 'Real estate', 'School & learning', 'Everyday life'];
const fields = {
 preferences: ['Your preferences', 'What food, budget, dietary needs or atmosphere matter?'], environment: ['Your setup', 'Which language, version and operating system? Add your experience level and any limits.'],
 audience: ['Audience', 'Who will use or read this?'], subject: ['Product, service, system or process', 'What is this about?'], facts: ['Verified facts', 'Which facts are confirmed?'], action: ['Desired action / next step', 'What should happen next?'], destination: ['Action destination', 'Where or how can readers act?'], limit: ['Word limit', 'What is the maximum number of words?'], impact: ['Confirmed impact', 'Who or what is affected?'], status: ['Current status', 'What is confirmed right now?'], taken: ['Actions taken', 'What has already been done?'], change: ['What to change', 'What needs improvement?'], preserve: ['What to preserve', 'What must stay intact?'], options: ['Options and criteria', 'Which options and decision criteria matter?'], goal: ['Goal and scope', 'What outcome, boundaries and dependencies matter?'], source: ['Original content', 'Paste the material to rewrite or summarize. URLs are not fetched.'], channel: ['Channel and format', 'Where will this be published, and what format suits that channel?'], duration: ['Meeting duration (minutes)', 'How much time is available?']
};
const specs = [
 ['study','Understand a topic',1,[5,6],'Learn something at your pace, with examples and practice.','Help me understand {{subject}}. My learning goal: {{goal}}. Match the explanation to {{audience}}.', ['subject','goal','audience'],'A clear explanation, a worked example, then a short practice question. Wait for my attempt before revealing its answer. Adapt to my answers and help me understand mistakes.'],
 ['dining','Find somewhere to eat',3,[6,5],'Find a place that fits your taste, location and budget.','Help me choose somewhere to eat in {{subject}}. Preferences: {{preferences}}. Occasion and priorities: {{goal}}.', ['subject','preferences','goal'],'A short list with reasons, tradeoffs and source links. If browsing is available, check recent menus, prices, opening hours and reviews. Otherwise say what cannot be verified and help me plan a search; do not fabricate restaurants or sources.'],
 ['creative','Make something original',0,[6,1,5],'Explore an idea for a story, video or personal project.','Help me develop {{subject}}. What I want to make: {{goal}}. Intended audience: {{audience}}.', ['subject','goal','audience'],'Three distinct directions, a recommendation with reasons, and an outline I can build on. Ask before expanding into a full draft.'],
 ['strategy','Build a market strategy',2,[4,1,3],'Shape a strategy around your market, goals and resources.','Help me create a market strategy for {{subject}}. Goal and boundaries: {{goal}}. Supplied market information: {{facts}}. Audience: {{audience}}.', ['subject','goal','facts','audience'],'Priorities, channel options, a phased plan, budget assumptions and measurable experiments. Separate supplied evidence from hypotheses. Verify current market data with dated sources if browsing is available; otherwise identify research needed. Do not invent market statistics or promise results.'],
 ['script','Build or debug a script',1,[0,5,6],'Work through PowerShell, automation or a tricky bug.','Help me write or debug a script. Desired behavior: {{goal}}. Environment: {{environment}}. Existing code, errors and sample input: {{source}}.', ['goal','environment','source'],'Clarify missing requirements, explain the approach, then provide a script, usage and meaningful tests. Match the specified runtime and skill level. Explain side effects and permissions; default to preview or dry-run for changes to files or systems. Never include real secrets.'],
 ['launch','Launch email',0,[1,2,3],'Announce a verified offering.','Write a launch email about {{subject}} for {{audience}}. Encourage {{action}} at {{destination}}.', ['subject','audience','facts','action','destination','limit'],'Two subject lines, preview text, body and call to action.'],
 ['homepage','Homepage introduction',0,[1,3],'Introduce your offering and its next step.','Write a homepage introduction about {{subject}} for {{audience}}. Guide readers to {{action}} at {{destination}}.', ['subject','audience','facts','action','destination','limit'],'Three headlines, introduction and CTA label.'],
 ['reply','Customer reply / follow-up',0,[2,0,3],'Answer a question or follow up using authorized actions.','Draft a customer reply or follow-up for {{audience}} about {{subject}}. Next step: {{action}}.', ['audience','subject','facts','action','source'],'Greeting, acknowledgment, answer and clear next step. Separate internal questions.'],
 ['email','Email or announcement',0,[0,1,2,3],'Communicate a change, request or announcement.','Write an email or announcement for {{audience}} about {{subject}}. Desired action: {{action}}.', ['audience','subject','facts','action','limit'],'Subject line, concise message and next step.'],
 ['incident','Incident update',0,[0,2,3],'Share confirmed impact and current progress.','Write a service interruption update for {{audience}} about {{subject}}.', ['audience','subject','impact','status','taken','action'],'Confirmed impact, current status, actions taken and next steps. Do not invent commitments or resolution times.'],
 ['guide','SOP or how-to guide',1,[0,2,3],'Document a repeatable process.','Explain how {{audience}} should carry out {{subject}}.', ['audience','subject','facts','goal'],'Purpose, prerequisites, numbered steps, checks and escalation. Flag unverified steps.'],
 ['technical','Technical explanation',1,[0,2,3],'Explain a system at the audience’s level.','Explain {{subject}} to {{audience}}.', ['subject','audience','facts','goal'],'Overview, how it works, relevant example and limitations. Define jargon.'],
 ['project','Project plan',2,[0,1,3],'Define scope, dependencies and implementation steps.','Create a project brief and implementation plan for {{subject}}. Goal and scope: {{goal}}.', ['subject','goal','audience','facts','action'],'Objective, scope, deliverables, dependencies, risks, milestones and next steps. Mark proposed owners and dates as proposals.'],
 ['agenda','Meeting agenda',2,[0,1,2,3],'Prepare a focused discussion with decisions.','Create a {{duration}} minute meeting agenda for {{audience}} about {{subject}}. Goal: {{goal}}.', ['audience','subject','goal','facts','duration'],'Objective, preparation, timed discussion items, decisions and action capture.'],
 ['compare','Compare options and tradeoffs',3,[0,1,2,3],'Assess options against explicit criteria.','Compare these options for {{audience}}: {{options}}. Goal: {{goal}}.', ['audience','options','goal','facts'],'Criteria table, tradeoffs, uncertainties and conditional recommendation. Separate facts from assumptions.'],
 ['rewrite','Critique or rewrite',3,[0,1,2,3],'Improve existing content while preserving what matters.','Critique and rewrite the original content for {{audience}}. Change: {{change}}. Preserve: {{preserve}}.', ['audience','change','preserve','source'],'Brief critique, revised content and explanation of changes. Preserve supplied facts.'],
 ['summary','Summary and action items',4,[0,1,2,3],'Extract key points, decisions and actions.','Summarize the supplied document or meeting notes for {{audience}}.', ['audience','source'],'Summary, decisions, action items with stated owners/dates, and open questions. Label missing owners and dates.'],
 ['social','Social post / repurpose content',0,[1,3],'Adapt source content to a channel.','Repurpose the original content about {{subject}} for {{audience}}. Channel and format: {{channel}}. Desired action: {{action}}.', ['subject','audience','source','channel','action','limit'],'Three post variations with a call to action. Preserve source claims.'],
 ['description','Service / product description or FAQ',1,[0,1,2,3],'Describe an offering and answer likely questions.','Describe {{subject}} for {{audience}} using verified facts.', ['subject','audience','facts','limit'],'Short description, benefits supported by facts and FAQ. Flag unanswered questions.'],
 ['listing','Write a listing description',0,[4,1],'Turn property facts into a clear listing description.','Write a listing description for {{subject}} for {{audience}}. Next step: {{action}} at {{destination}}.', ['subject','facts','audience','action','destination','limit'],'Headline, property description, supplied features and a next step to arrange a viewing. Use a warm, specific tone.'],
 ['inquiry','Reply to a buyer or seller inquiry',0,[4,2],'Answer a property question using facts you provide.','Reply to this buyer or seller inquiry about {{subject}}. Audience: {{audience}}. Next step: {{action}}.', ['subject','audience','source','facts','action'],'Friendly acknowledgment, answers supported by supplied facts and a clear next step. Separate questions for the agent.'],
 ['openhouse','Open house follow-up email',0,[4,1],'Follow up with a visitor after an open house.','Write an open house follow-up email about {{subject}} for {{audience}}. Encourage {{action}} at {{destination}}.', ['subject','audience','facts','action','destination','limit'],'Subject line, thank-you, relevant supplied property details and a next step. Use a warm, helpful tone.']
];
const constraints = {
 launch:'Do not invent prices, dates, testimonials or performance claims.',
 homepage:'Do not invent credentials, customer results or guarantees. Avoid jargon and generic claims.',
 reply:'Use only confirmed policies and authorized actions. Do not promise refunds, admit liability or commit to unconfirmed timelines. Omit unnecessary private information.',
 incident:'Report only confirmed impact and status. Do not invent commitments or resolution times.',
 guide:'Flag unverified steps, prerequisites and permissions. Do not invent a process.',
 compare:'Use explicit criteria; distinguish facts from assumptions and do not invent evidence.',
 rewrite:'Preserve supplied facts and the specified elements; explain substantive changes.',
 summary:'Do not invent decisions, owners or deadlines. Mark anything not stated as missing.'
};
constraints.listing = 'Use only supplied property facts. Do not invent features, availability, prices, neighborhood claims or guarantees.';
constraints.inquiry = 'Use only supplied facts and authorized next steps. Do not invent availability, appointments, financing terms or commitments.';
constraints.openhouse = 'Do not invent visitor preferences, property features, offers, appointments or deadlines. Avoid pressure and unsupported claims.';
export const library = Object.fromEntries(specs.map(([key,name,category,tags,description,task,keys,output]) => [key, {
 name, category: categories[category], roles: tags.map(i => roles[i]), description, deliverable: output, outside:['study','dining','creative','strategy','script'].includes(key),
 variables: keys.map(field => ({key:field,label:fields[field][0],help:fields[field][1],required:!(key==='script' && field==='source' || key==='strategy' && field==='facts')})),
 blocks: [{type:'task',value:task}, {type:'context',value:keys.filter(k => !['source','limit'].includes(k)).map(k => `${fields[k][0]}: {{${k}}}`).join('\n')}, {type:'constraints',value:'Use supplied facts. Do not invent claims, policies, prices or timelines. '+(constraints[key] ?? '') + (keys.includes('limit') ? ' Maximum {{limit}} words.' : '')}, {type:'output',value:output}, ...(keys.includes('source') ? [{type:'original',value:'{{source}}'}] : []), ...(['launch','reply'].includes(key) ? [{type:'tone',value:key === 'reply' ? 'Empathetic, calm and direct. Avoid blame and canned apologies.' : 'Clear, welcoming and specific. Avoid hype and pressure.'}] : [])]
}]));
